 solid #a0b5ed;border-radius:3px;font-size:15px}.smallrow{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #619795;padding:7px 0}.grow{flex:1;min-height:0;overflow:auto}.inspector{display:flex;flex-direction:column;height:100%;min-height:0}.inspector>header{flex:none}.subhead{padding:8px 12px;border-bottom:1px solid #90a6c2}.subhead p{margin:3px 0}.reading{overflow:auto;flex:1;min-height:0;padding:12px;font-size:14px}.inspector>footer{padding:8px 12px;background:#1a2943;border-top:1px solid #a7b9d7;display:flex;align-items:center;gap:14px;flex-wrap:wrap;flex:none}.inspector>footer p{margin:0;font-size:12px}.twocol{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.card{padding:10px;border:1px solid #9caecd;border-radius:4px;background:#172a43;min-width:0}.card h3{font-size:15px;margin:0 0 8px}.card p{margin:5px 0}dl{margin:0}dt{font-weight:600;margin-top:9px}dd{margin:3px 0;color:#d4def1}table{border-collapse:collapse;width:100%;font-size:14px;table-layout:fixed}td,th{text-align:left;vertical-align:top;padding:9px 8px;border-bottom:1px solid #9caecd;overflow-wrap:anywhere}th{background:#342657}caption{text-align:left;font-weight:600;margin-bottom:8px}details{border-top:1px solid #9caecd;padding:8px 0}summary{cursor:pointer;color:#ffe184;font-weight:600}.timeline{list-style:none;margin:0;padding:0}.timeline li{padding:10px 10px 10px 14px;border-left:3px solid #d998eb;border-bottom:1px solid #9caecd}.timeline time{font-variant-numeric:tabular-nums;color:#d4def1}.timeline h3{font-size:15px;margin:4px 0}.timeline p{margin:4px 0}.tree{display:flex;flex-direction:column;gap:8px}.relation{padding:4px 8px;border-left:2px dashed #d2bcff;margin-left:18px}.relation.proof{border-left-style:solid}.comparison .wide-only{display:none}.skin{border-top:3px solid var(--accent,#89c6d8)}.skin h3{font-family:Georgia,serif;font-size:16px}.skin.scan h3{font-family:monospace}.skin .source{color:#ffe184}.skins{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bottom{height:44px;display:flex;align-items:center;padding:8px 12px;background:#202c51;border-top:1px solid #a7b9d7;gap:18px;font-size:14px}.bottom span{margin-left:auto;font-size:12px}.viewnav{display:flex;gap:10px;font-size:13px}.viewnav a[aria-current]{color:#ffe184;font-weight:700}.no-margin{margin:0}.notice{padding:8px 12px;background:#1a2943;font-size:13px}.nowrap{white-space:nowrap}@media(min-width:1700px){.board{grid-template-columns:300px 440px minmax(0,1fr)}.comparison .wide-only{display:table-cell}.bodylayers{display:grid;grid-template-columns:1fr 1fr;gap:16px}.skins{grid-template-columns:repeat(2,1fr)}.reading{font-size:15px}}'''
